content.css:
.hierarchy-selector {
  box-sizing: border-box;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  height: 100%;
  padding: 12px;
  overflow: auto;
  font-family: Arial, sans-serif;
}
.hierarchy-level {
  box-sizing: border-box;
  display: flex;
  flex: 1 1 0;
  min-width: 140px;
  flex-direction: column;
  gap: 6px;
}
.hierarchy-level__label {
  overflow: hidden;
  font-size: 12px;
  font-weight: 600;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hierarchy-level__button {
  box-sizing: border-box;
  width: 100%;
  min-height: 36px;
  padding: 8px 12px;
  border: 1px solid #8a8886;
  border-radius: 4px;
  background: #ffffff;
  color: #242424;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.hierarchy-level__button:hover {
  background: #f5f5f5;
}
.hierarchy-level__button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}
.hierarchy-selector__landing-page {
  box-sizing: border-box;
  display: flex;
  width: 100%;
  height: 100%;
  min-height: 100px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
}
.hierarchy-selector__landing-heading {
  margin-bottom: 6px;
  font-size: 16px;
  font-weight: 600;
  line-height: 22px;
}
.hierarchy-selector__landing-text {
  max-width: 300px;
  font-size: 12px;
  line-height: 18px;
}
